const {spawnSync} = require('child_process');
const BIN = '/workspace/dataset/test4_executable';
// CORRECTED separator set: ASCII punctuation + ASCII whitespace, EXCLUDING backslash 0x5C
const SEPSTR = "!\"#$%&'()*+,-./:;<=>?@[]^_`{|}~ \t\n\r\x0b\x0c";
const SEP = new Set(SEPSTR.split(''));
function slugifyRef(text) {
  if (text === '') return '';
  const parts = []; let cur = '';
  for (const ch of text) {
    if (ch.length === 1 && SEP.has(ch)) { if (cur) { parts.push(cur); cur = ''; } }
    else cur += ch;
  }
  if (cur) parts.push(cur);
  let ret = parts.join('_');
  if (ret === '') ret = '_';
  const low = ret.toLowerCase();
  return low === '' ? ret : low;
}
function expect(valueBuf) {
  let b = Buffer.from(valueBuf);
  const z = b.indexOf(0); if (z >= 0) b = b.subarray(0, z); // NUL truncation at C boundary
  const text = b.toString('utf8');                          // UTF-8 decode w/ U+FFFD
  return Buffer.concat([Buffer.from(slugifyRef(text), 'utf8'), Buffer.from([0x0a])]);
}
function runA(v, env) {
  const o = {encoding: 'buffer', maxBuffer: 1 << 28};
  if (env) o.env = env;
  const r = spawnSync(BIN, ['--a', v], o);
  return {code: r.status, out: r.stdout || Buffer.alloc(0), err: r.stderr || Buffer.alloc(0)};
}
module.exports = {SEP, SEPSTR, slugifyRef, expect, runA, hex: b => Buffer.from(b).toString('hex')};

